triggers_mc.aqua_mc.triggerFunction = function()
{
   ENGINE.sendJoinGame("aqua",true);
};
aqua_mc.onRollOut = function()
{
   INTERFACE.closeHint();
};
aqua_mc.onRollOver = function()
{
   INTERFACE.showHint(this.hint_mc,"aqua_hint");
   if(this._currentframe >= 1 && this._currentframe <= 80)
   {
      this.gotoAndPlay(81);
   }
   else if(this._currentframe >= 400 && this._currentframe <= 486)
   {
      this.gotoAndPlay(81);
   }
};
aqua_mc.onRelease = function()
{
   ENGINE.sendPlayerMove(635,160);
   if(this._currentframe >= 1 && this._currentframe <= 180)
   {
      this.gotoAndPlay(181);
   }
   else if(this._currentframe >= 348 && this._currentframe <= 357)
   {
      this.gotoAndPlay(192);
   }
   else if(this._currentframe >= 358 && this._currentframe <= 363)
   {
      this.gotoAndPlay(186);
   }
   else if(this._currentframe >= 364 && this._currentframe <= 399)
   {
      gotoAndPlay(181);
   }
   else if(this._currentframe >= 400 && this._currentframe <= 486)
   {
      this.gotoAndPlay(487);
   }
};
